sources.packages/control-plane/src/review.js:
1: // Deploy review: one Anthropic call per deploy, run in ctx.waitUntil concurrent with
2: // the Fly build. A control, not a chat — fixed prompt, schema-forced JSON, risk
3: // computed here in code. Must never break a deploy: every failure path just logs.
4: 
5: const MODEL = 'claude-opus-5';
6: 
7: // Outbound hosts that don't raise risk on their own. `*.x` matches x and subdomains.
8: const ALLOWED_HOSTS = ['api.stripe.com', '*.amazonaws.com', 'api.openai.com', 'api.anthropic.com'];
9: 
10: const SYSTEM_PROMPT = [
11:   'You are a deploy-time code reviewer for a hosting platform. You receive one Python',
12:   'app as a bundle of source files, each prefixed with === path ===, plus requirements.txt',
13:   'and small.toml (which declares required secrets under [secrets] required).',
14:   'Report what the app touches. Trace user input across files. Secret values are redacted',
15:   'before you see them — reason from names and line numbers only.',
16:   'Fill every field of the output schema; use empty arrays where a category does not apply.',
17:   'summary: one plain-English sentence saying what the app does.',
18:   'secrets: environment variables the code reads; declared = whether small.toml declares them.',
19:   'undeclared_secrets: names the code reads that small.toml does not declare.',
20:   'outbound: network destinations the code contacts. aws: AWS API actions and resources.',
21:   'shell_exec: subprocess/os.system/exec calls; user_input_reaches_it = true when data from',
22:   'a request can reach the command, including across files.',
23:   'user_input: request inputs traced to the sinks they flow into.',
24:   'findings: concrete security-relevant observations. Locations are path:line.',
25:   'risk: your overall estimate — low, medium, or high.',
26:   'runbook: a complete RUNBOOK.md in markdown for a colleague who did not write this app,',
27:   'with these sections in this exact order: a # title (the app name); the line',
28:   '"> Generated by `small` from the code — regenerated on every deploy.";',
29:   '## What it does; ## Who it\'s for; ## How to run it locally;',
30:   '## What it needs (table: Secret | Used in | For — every env var the code reads, named by the',
31:   'file:line where it is read and what that code does with the value; include platform-provided',
32:   'SMALL_* vars marked "(set by the platform)"); ## Files (table: File | Role);',
33:   '## Commands (table: What | Command); ## Endpoints (server apps: table of the routes the code',
34:   'defines) or ## Schedule (job apps: when and how runs start); ## What it talks to;',
35:   '## Known limits; ## If it breaks (table: Symptom | Likely cause | Where to look).',
36:   'Runbook rules: start from the entry file and trace imports outward. Every command must be',
37:   'copy-pasteable and must exist in the code — derive commands from if __name__ == "__main__"',
38:   'blocks, argparse, the Makefile, and scripts/. Apps with kind = "job" in small.toml are started',
39:   'with `small run <name>`; server apps redeploy with `small deploy`. Leave a section out rather',
40:   'than invent content. Never include secret values. Do not write the final *review:* line — it',
41:   'is appended after review.',
42: ].join(' ');
43: 
44: const S = { type: 'string' };
45: const arr = (items) => ({ type: 'array', items });
46: const obj = (properties) => ({ type: 'object', properties, required: Object.keys(properties), additionalProperties: false });
47: 
48: const REVIEW_SCHEMA = obj({
49:   summary: S,
50:   risk: { type: 'string', enum: ['low', 'medium', 'high'] },
51:   secrets: arr(obj({ name: S, declared: { type: 'boolean' }, used_at: S })),
52:   undeclared_secrets: arr(S),
53:   outbound: arr(obj({ host: S, purpose: S, at: S })),
54:   aws: arr(obj({ action: S, resource: S, at: S })),
55:   filesystem: obj({ reads: arr(S), writes: arr(S) }),
56:   shell_exec: arr(obj({ command: S, user_input_reaches_it: { type: 'boolean' }, at: S })),
57:   user_input: arr(obj({ source: S, flows_to: S, validated: { type: 'boolean' } })),
58:   findings: arr(obj({ severity: { type: 'string', enum: ['low', 'medium', 'high'] }, at: S, text: S })),
59:   skipped: arr(S),
60:   runbook: S,
61: });
62: 
63: function hostAllowed(host) {
64:   return ALLOWED_HOSTS.some((p) =>
65:     p.startsWith('*.') ? host === p.slice(2) || host.endsWith(p.slice(1)) : host === p
66:   );
67: }
68: 
69: // Risk comes from these rules, never from the model.
70: function computeRisk(review) {
71:   if ((review.shell_exec || []).some((s) => s.user_input_reaches_it)) return 'high';
72:   if ((review.undeclared_secrets || []).length) return 'medium';
73:   if ((review.outbound || []).some((o) => !hostAllowed(o.host))) return 'medium';
74:   return 'low';
75: }
76: 
77: const SEVERITY = { high: 0, medium: 1, low: 2 };
78: 
79: function validateReview(r) {
80:   if (!r || typeof r !== 'object') throw new Error('review is not an object');
81:   if (typeof r.summary !== 'string') throw new Error('review: bad summary');
82:   if (typeof r.runbook !== 'string' || !r.runbook.trim()) throw new Error('review: bad runbook');
83:   for (const k of ['secrets', 'undeclared_secrets', 'outbound', 'aws', 'shell_exec', 'user_input', 'findings', 'skipped']) {
84:     if (!Array.isArray(r[k])) throw new Error(`review: ${k} is not an array`);
85:   }
86:   if (!r.filesystem || !Array.isArray(r.filesystem.reads) || !Array.isArray(r.filesystem.writes)) {
87:     throw new Error('review: bad filesystem');
88:   }
89:   return r;
90: }
91: 
92: async function fetchReview(env, bundle) {
93:   const resp = await fetch('https://api.anthropic.com/v1/messages', {
94:     method: 'POST',
95:     headers: {
96:       'x-api-key': env.ANTHROPIC_API_KEY,
97:       'anthropic-version': '2023-06-01',
98:       'anthropic-beta': 'server-side-fallback-2026-07-01',
99:       'Content-Type': 'application/json',
100:       // identity-linked (non-workspace-scoped) keys must name the workspace per request
101:       ...(env.ANTHROPIC_WORKSPACE_ID ? { 'anthropic-workspace-id': env.ANTHROPIC_WORKSPACE_ID } : {}),
102:     },
103:     body: JSON.stringify({
104:       model: MODEL,
105:       max_tokens: 16000,
106:       fallbacks: 'default', // safety classifiers can decline; re-run on the recommended model
107:       system: SYSTEM_PROMPT,
108:       output_config: { format: { type: 'json_schema', schema: REVIEW_SCHEMA } },
109:       messages: [{ role: 'user', content: bundle }],
110:     }),
111:   });
112:   if (!resp.ok) throw new Error(`anthropic ${resp.status}`);
113:   const msg = await resp.json();
114:   if (msg.stop_reason === 'refusal') throw new Error('model refused');
115:   const text = (msg.content || []).find((b) => b.type === 'text');
116:   if (!text) throw new Error('no text block in response');
117:   return validateReview(JSON.parse(text.text));
118: }
119: 
120: function finishReview(review, skipped) {
121:   review.skipped = skipped || []; // the CLI knows what it left out; the model can't
122:   // SMALL_* vars are platform-injected (SMALL_DATA, SMALL_USER, ...), not app secrets.
123:   review.secrets = review.secrets.filter((s) => !s.name.startsWith('SMALL_'));
124:   review.undeclared_secrets = review.undeclared_secrets.filter((n) => !n.startsWith('SMALL_'));
125:   review.risk = computeRisk(review);
126:   review.findings.sort((a, b) => (SEVERITY[a.severity] ?? 3) - (SEVERITY[b.severity] ?? 3));
127:   // The review summary line at the bottom of every runbook — risk comes from computeRisk, not the model.
128:   review.runbook = review.runbook.trimEnd() + `\n\n---\n*review: ${review.summary} — risk: ${review.risk}*\n`;
129:   return review;
130: }
131: 
132: async function runReview(env, appId, bundle, skipped) {
133:   try {
134:     const review = finishReview(await fetchReview(env, bundle), skipped);
135:     if (review.risk === 'high') console.log(`review: HIGH risk on app ${appId}: ${review.summary}`);
136:     await env.DB.prepare(
137:       "UPDATE apps SET review_prev = review, review = ?, reviewed_at = datetime('now'), review_model = ? WHERE id = ?"
138:     ).bind(JSON.stringify(review), MODEL, appId).run();
139:   } catch (e) {
140:     // Never let the review break (or block) a deploy — the CLI shows "review: unavailable".
141:     console.log(`review failed for app ${appId}: ${e.message}`);
142:   }
143: }
144: 
145: // Synchronous path for `small init`: same model call, no app row yet — the CLI writes the file.
146: async function generateRunbook(env, bundle) {
147:   return finishReview(await fetchReview(env, bundle), []).runbook;
148: }
149: 
150: export { runReview, generateRunbook, computeRisk, validateReview, hostAllowed, MODEL };

sources.packages/control-plane/src/index.js:
1: // small control plane: CLI API + browser auth wall + router. One Worker + D1.
2: // URLs are path-based (no custom domain): /a/<org>/<app>/... proxies to the app's Fly origin.
3: import { sign, verify, sha256, randomHex } from './token.js';
4: import { ensureFlyApp, ensureVolume, deployTokenFor, startMachine } from './fly.js';
5: import { assumeRole } from './aws.js';
6: import { runReview, generateRunbook } from './review.js';
7: import { parseCron, matches, nextRun } from './cron.js';
8: 
9: const SESSION_COOKIE = 'small_session';
10: const SESSION_TTL = 7 * 24 * 3600;
11: 
12: const orgOf = (email) => email.split('@')[1].toLowerCase().replace(/\./g, '-');
13: const now = () => Math.floor(Date.now() / 1000);
14: const json = (data, status = 200) => new Response(JSON.stringify(data), { status, headers: { 'Content-Type': 'application/json' } });
15: const html = (body, status = 200, headers = {}) =>
16:   new Response(`<!doctype html><meta name=viewport content="width=device-width,initial-scale=1"><style>body{font-family:system-ui;max-width:26rem;margin:15vh auto;padding:0 1rem}input,button{font-size:1rem;padding:.5rem}</style>${body}`, {
17:     status,
18:     headers: { 'Content-Type': 'text/html;charset=utf-8', ...headers },
19:   });
20: 
21: async function sendEmail(env, to, subject, text) {
22:   if (!env.RESEND_API_KEY) return false; // dev mode: caller falls back to echoing the code/link
23:   const resp = await fetch('https://api.resend.com/emails', {
24:     method: 'POST',
25:     headers: { Authorization: `Bearer ${env.RESEND_API_KEY}`, 'Content-Type': 'application/json' },
26:     body: JSON.stringify({ from: env.EMAIL_FROM || 'small <[REDACTED]>', to: [to], subject, text }),
27:   });
28:   return resp.ok;
29: }
30: 
31: async function cliAuth(req, env) {
32:   const m = (req.headers.get('Authorization') || '').match(/^Bearer (.+)$/);
33:   if (!m) return null;
34:   const p = await verify(m[1], env.MASTER_KEY);
35:   return p && p.t === 'cli' ? p : null;
36: }
37: 
38: async function sessionOf(req, env) {
39:   const header = req.headers.get('X-Small-Session'); // tests use the header; browsers use the cookie
40:   const cookie = (req.headers.get('Cookie') || '').match(new RegExp(`${SESSION_COOKIE}=([^;]+)`));
41:   const p = await verify(header || (cookie && cookie[1]), env.MASTER_KEY);
42:   return p && p.t === 'sess' ? p : null;
43: }
44: 
45: async function appRow(env, org, name) {
46:   return env.DB.prepare('SELECT * FROM apps WHERE org = ? AND name = ?').bind(org, name).first();
47: }
48: 
49: async function canView(env, app, email) {
50:   if (app.owner_email === email) return true;
51:   const member = await env.DB.prepare('SELECT role FROM members WHERE app_id = ? AND email = ?').bind(app.id, email).first();
52:   if (member) return true;
53:   return app.visibility === 'domain' && orgOf(email) === app.org;
54: }
55: 
56: async function canEdit(env, app, email) {
57:   if (app.owner_email === email) return true;
58:   const member = await env.DB.prepare('SELECT role FROM members WHERE app_id = ? AND email = ?').bind(app.id, email).first();
59:   return member && member.role === 'edit';
60: }
61: 
62: // ---------- CLI API ----------
63: 
64: async function apiLogin(req, env) {
65:   const { email } = await req.json();
66:   if (!email || !email.includes('@')) return json({ error: 'valid email required' }, 400);
67:   const code = String(crypto.getRandomValues(new Uint32Array(1))[0] % 1000000).padStart(6, '0');
68:   const challenge = await sign({ t: 'challenge', email, codeHash: await sha256(code), exp: now() + 600 }, env.MASTER_KEY);
69:   const sent = await sendEmail(env, email, `small login code: ${code}`, `Your small login code is ${code}\nIt expires in 10 minutes.`);
70:   if (sent) return json({ challenge });
71:   // Echoing the code is an auth bypass — only allowed on test/dev instances (marked by TEST_BYPASS_SECRET).
72:   if (!env.TEST_BYPASS_SECRET) return json({ error: 'email not configured on this control plane' }, 503);
73:   return json({ challenge, devCode: code, warning: 'test instance — code echoed' });
74: }
75: 
76: async function apiVerify(req, env) {
77:   const { challenge, code } = await req.json();
78:   const p = await verify(challenge, env.MASTER_KEY);
79:   if (!p || p.t !== 'challenge' || p.codeHash !== (await sha256(String(code)))) return json({ error: 'bad or expired code' }, 401);
80:   // ponytail: CLI tokens never expire; revoke by rotating MASTER_KEY. Add exp + refresh when it matters.
81:   const token = await sign({ t: 'cli', email: p.email, org: orgOf(p.email) }, env.MASTER_KEY);
82:   return json({ token, email: p.email, org: orgOf(p.email) });
83: }
84: 
85: async function apiDeploy(req, env, ctx, user, baseUrl) {
86:   const { name, framework, visibility, awsRoleArn, kind, review, storage, schedule } = await req.json();
87:   if (!name || !/^[a-z0-9-]{1,40}$/.test(name)) return json({ error: 'name must be [a-z0-9-]' }, 400);
88:   let nextAt = null;
89:   if (schedule) {
90:     if (kind !== 'job') return json({ error: 'schedule requires kind = "job" in small.toml' }, 400);
91:     try {
92:       nextAt = nextRun(parseCron(schedule), Date.now()); // also rejects "0 0 30 2 *" — valid syntax, never fires
93:     } catch (e) {
94:       return json({ error: `bad schedule "${schedule}": ${e.message} — use 5-field cron like "0 9 * * 1-5"` }, 400);
95:     }
96:   }
97:   if (storage && !(Number.isInteger(storage.sizeGb) && storage.sizeGb >= 1 && storage.sizeGb <= 100))
98:     return json({ error: 'storage.sizeGb must be an integer between 1 and 100' }, 400);
99:   if (awsRoleArn && !/^arn:aws:iam::\d{12}:role\/[\w+=,.@/-]+$/.test(awsRoleArn)) return json({ error: 'bad aws role arn' }, 400);
100:   let app = await appRow(env, user.org, name);
101:   if (app) {
102:     if (!(await canEdit(env, app, user.email))) return json({ error: `${name} exists and you cannot edit it` }, 403);
103:     if (visibility) await env.DB.prepare('UPDATE apps SET visibility = ? WHERE id = ?').bind(visibility, app.id).run();
104:     if (awsRoleArn !== undefined) await env.DB.prepare('UPDATE apps SET aws_role_arn = ? WHERE id = ?').bind(awsRoleArn || null, app.id).run();
105:     if (kind) await env.DB.prepare('UPDATE apps SET kind = ? WHERE id = ?').bind(kind === 'job' ? 'job' : 'server', app.id).run();
106:     if (schedule !== undefined) await env.DB.prepare('UPDATE apps SET schedule = ? WHERE id = ?').bind(schedule || null, app.id).run();
107:   } else {
108:     const flyApp = `small-${name}-${randomHex(3)}`;
109:     await env.DB.prepare('INSERT INTO apps (org, name, fly_app, proxy_secret, visibility, owner_email, aws_role_arn, kind, schedule) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)')
110:       .bind(user.org, name, flyApp, randomHex(32), visibility || 'domain', user.email, awsRoleArn || null, kind === 'job' ? 'job' : 'server', schedule || null)
111:       .run();
112:     app = await appRow(env, user.org, name);
113:   }
114:   if (!env.FLY_API_TOKEN) return json({ error: 'control plane has no FLY_API_TOKEN configured' }, 503);
115:   // The worker owns the Fly app lifecycle; the CLI only gets a 1h token scoped to this one app.
116:   let flyToken, volumeRegion;
117:   try {
118:     await ensureFlyApp(env, app.fly_app);
119:     if (storage) volumeRegion = await ensureVolume(env, app.fly_app, storage.sizeGb);
120:     flyToken = await deployTokenFor(env, app);
121:   } catch (e) {
122:     return json({ error: e.message }, 502);
123:   }
124:   // Review runs concurrently with the CLI-side Fly build; it never blocks or fails the deploy.
125:   const reviewStarted = !!(env.ANTHROPIC_API_KEY && review && review.bundle);
126:   if (reviewStarted) ctx.waitUntil(runReview(env, app.id, review.bundle, review.skipped || []));
127:   return json({
128:     flyApp: app.fly_app,
129:     proxySecret: app.proxy_secret,
130:     flyToken,
131:     url: `${baseUrl}/a/${user.org}/${name}/`,
132:     framework: framework || null,
133:     volumeRegion: volumeRegion || null,
134:     reviewStarted,
135:     reviewedAt: app.reviewed_at || null, // previous review's stamp; the CLI polls until it changes
136:     nextRun: nextAt,
137:     schedulePaused: !!app.schedule_paused,
138:   });
139: }
140: 
141: async function apiReview(req, env, user) {
142:   const name = new URL(req.url).searchParams.get('app');
143:   const app = await appRow(env, user.org, name);
144:   if (!app) return json({ error: `no app named ${name}` }, 404);
145:   if (!(await canView(env, app, user.email))) return json({ error: 'no access' }, 403);
146:   return json({
147:     review: app.review ? JSON.parse(app.review) : null,
148:     prev: app.review_prev ? JSON.parse(app.review_prev) : null,
149:     reviewedAt: app.reviewed_at || null,
150:     model: app.review_model || null,
151:   });
152: }
153: 
154: // Deploy-time review, run while the CLI holds the request open (in parallel with its Fly
155: // build). waitUntil's ~30s window is too short for the model to write review + runbook —
156: // this handler awaits the model and stores the result before responding. runReview never
157: // throws, so a model failure still answers 200 with the previous (or no) review.
158: async function apiReviewRun(req, env, user) {
159:   const { app: name, bundle, skipped } = await req.json();
160:   const app = await appRow(env, user.org, name);
161:   if (!app) return json({ error: `no app named ${name}` }, 404);
162:   if (!(await canEdit(env, app, user.email))) return json({ error: 'no access' }, 403);
163:   if (!env.ANTHROPIC_API_KEY || !bundle) return json({ error: 'review not configured' }, 503);
164:   await runReview(env, app.id, bundle, skipped || []);
165:   const fresh = await appRow(env, user.org, name);
166:   return json({
167:     review: fresh.review ? JSON.parse(fresh.review) : null,
168:     reviewedAt: fresh.reviewed_at || null,
169:     model: fresh.review_model || null,
170:   });
171: }
172: 
173: // `small init` sends a bundle before any app row exists; the runbook comes back
174: // synchronously and the CLI writes RUNBOOK.md. Deploys store theirs via runReview.
175: async function apiRunbook(req, env) {
176:   const { bundle } = await req.json();
177:   if (!bundle) return json({ error: 'bundle required' }, 400);
178:   if (!env.ANTHROPIC_API_KEY) return json({ error: 'runbook generation not configured on this control plane' }, 503);
179:   try {
180:     return json({ runbook: await generateRunbook(env, bundle) });
181:   } catch (e) {
182:     return json({ error: e.message }, 502);
183:   }
184: }
185: 
186: async function apiShare(req, env, user) {
187:   const { app: name, email, role } = await req.json();
188:   const app = await appRow(env, user.org, name);
189:   if (!app) return json({ error: `no app named ${name}` }, 404);
190:   if (!(await canEdit(env, app, user.email))) return json({ error: 'only owner or edit members can share' }, 403);
191:   await env.DB.prepare('INSERT INTO members (app_id, email, role) VALUES (?, ?, ?) ON CONFLICT(app_id, email) DO UPDATE SET role = excluded.role')
192:     .bind(app.id, email.toLowerCase(), role === 'edit' ? 'edit' : 'view')
193:     .run();
194:   return json({ ok: true, app: name, email: email.toLowerCase(), role: role === 'edit' ? 'edit' : 'view' });
195: }
196: 
197: async function apiApps(env, user) {
198:   const { results } = await env.DB.prepare('SELECT name, visibility, owner_email, fly_app, created_at FROM apps WHERE org = ? ORDER BY name').bind(user.org).all();
199:   return json({ apps: results });
200: }
201: 
202: async function apiLogs(req, env, user) {
203:   const name = new URL(req.url).searchParams.get('app');
204:   const app = await appRow(env, user.org, name);
205:   if (!app) return json({ error: `no app named ${name}` }, 404);
206:   if (!(await canView(env, app, user.email))) return json({ error: 'no access' }, 403);
207:   if (!env.FLY_API_TOKEN) return json({ error: 'control plane has no FLY_API_TOKEN configured' }, 503);
208:   try {
209:     return json({ flyApp: app.fly_app, flyToken: await deployTokenFor(env, app) });
210:   } catch (e) {
211:     return json({ error: e.message }, 502);
212:   }
213: }
214: 
215: // Called by guard.py with the app's proxy secret — not a CLI token.
216: async function apiRequestLogIngest(req, env, slug) {
217:   const m = (req.headers.get('Authorization') || '').match(/^Bearer (.+)$/);
218:   const app = m && (await env.DB.prepare('SELECT * FROM apps WHERE proxy_secret = ?').bind(m[1]).first());
219:   if (!app || app.name !== slug) return json({ error: 'forbidden' }, 403);
220:   const { lines = [] } = await req.json();
221:   if (!Array.isArray(lines) || !lines.length) return json({ ok: true });
222:   const stmt = env.DB.prepare('INSERT INTO request_logs (org, slug, ts, method, path, status, ms, user) VALUES (?, ?, ?, ?, ?, ?, ?, ?)');
223:   await env.DB.batch(
224:     lines.slice(0, 500).map((l) =>
225:       stmt.bind(app.org, app.name, String(l.ts || ''), String(l.method || ''), String(l.path || ''), Number(l.status) || 0, Number(l.ms) || 0, l.user == null ? null : String(l.user))
226:     )
227:   );
228:   return json({ ok: true });
229: }
230: 
231: // ponytail: no log search — user/status filters only, add a path/text query param when asked
232: async function apiRequestLogs(req, env, user) {
233:   const url = new URL(req.url);
234:   const name = url.searchParams.get('app');
235:   const app = await appRow(env, user.org, name);
236:   if (!app) return json({ error: `no app named ${name}` }, 404);
237:   if (!(await canView(env, app, user.email))) return json({ error: 'no access' }, 403);
238:   const where = ['org = ?', 'slug = ?'];
239:   const binds = [app.org, app.name];
240:   const byUser = url.searchParams.get('user');
241:   if (byUser) { where.push('user = ?'); binds.push(byUser); }
242:   const byStatus = url.searchParams.get('status') || '';
243:   if (/^[1-5]xx$/.test(byStatus)) { where.push('status BETWEEN ? AND ?'); binds.push(+byStatus[0] * 100, +byStatus[0] * 100 + 99); }
244:   else if (/^\d+$/.test(byStatus)) { where.push('status = ?'); binds.push(+byStatus); }
245:   const after = url.searchParams.get('after');
246:   const order = after === null ? 'ORDER BY id DESC LIMIT 100' : 'ORDER BY id LIMIT 1000'; // no cursor: last 100 newest-first; cursor: ascending for --follow
247:   if (after !== null) { where.push('id > ?'); binds.push(+after); }
248:   const { results } = await env.DB.prepare(`SELECT id, ts, method, path, status, ms, user FROM request_logs WHERE ${where.join(' AND ')} ${order}`).bind(...binds).all();
249:   const cursor = results.length ? Math.max(results[0].id, results[results.length - 1].id) : +(after || 0);
250:   return json({ lines: results, cursor });
