253: // Runtime endpoint: the guard inside a machine trades its proxy secret for 1h STS
254: // session creds scoped by the customer's role. No CLI token involved — the proxy
255: // secret is per-app and high-entropy. ExternalId pins the role to the app's org so
256: // one org cannot point small.toml at another org's role (confused deputy).
257: async function apiAwsCreds(req, env) {
258:   const { secret } = await req.json();
259:   if (!secret) return json({ error: 'secret required' }, 400);
260:   const app = await env.DB.prepare('SELECT * FROM apps WHERE proxy_secret = ?').bind(secret).first();
261:   if (!app) return json({ error: 'forbidden' }, 403);
262:   if (!app.aws_role_arn) return json({ error: 'no aws role configured for this app' }, 404);
263:   if (!env.AWS_ACCESS_KEY_ID || !env.AWS_SECRET_ACCESS_KEY) return json({ error: 'control plane has no AWS principal configured' }, 503);
264:   try {
265:     return json(await assumeRole(env, app.aws_role_arn, `small-${app.org}-${app.name}`, app.org));
266:   } catch (e) {
267:     return json({ error: e.message }, 502);
268:   }
