284: // Shared by the manual /api/runs path and the cron tick. startedBy = email or "cron".
285: // Marks the run failed and rethrows if the machine won't start.
286: async function startRun(env, app, startedBy, baseUrl) {
287:   const runId = 'r-' + randomHex(6);
288:   await env.DB.prepare('INSERT INTO runs (run_id, app_id, started_by) VALUES (?, ?, ?)').bind(runId, app.id, startedBy).run();
289:   const runToken = await sign({ t: 'run', run: runId, exp: now() + 6 * 3600 }, env.MASTER_KEY);
290:   try {
291:     await startMachine(env, app.fly_app, {
292:       image: app.image,
293:       auto_destroy: true,
294:       restart: { policy: 'no' },
295:       guest: { cpu_kind: 'shared', cpus: 1, memory_mb: 256 }, // ponytail: fixed size; read memory from small.toml when a job needs more
296:       env: {
297:         SMALL_RUN_ID: runId,
298:         SMALL_RUN_TOKEN: runToken,
299:         SMALL_USER: startedBy,
300:         SMALL_API: baseUrl,
301:         ...(startedBy === 'cron' ? { SMALL_TRIGGER: 'cron' } : {}),
302:       },
303:     });
304:   } catch (e) {
305:     await env.DB.prepare("UPDATE runs SET status = 'failed', finished_at = datetime('now') WHERE run_id = ?").bind(runId).run();
306:     throw e;
307:   }
308:   return runId;
309: }
