364: // Called by runner.py with the per-run token — not a CLI token.
365: async function apiRunLog(req, env, runId) {
366:   const m = (req.headers.get('Authorization') || '').match(/^Bearer (.+)$/);
367:   const p = m && (await verify(m[1], env.MASTER_KEY));
368:   if (!p || p.t !== 'run' || p.run !== runId) return json({ error: 'bad run token' }, 401);
369:   const { lines = [], exitCode } = await req.json();
370:   if (lines.length) {
371:     // ponytail: MAX(seq) is race-free only because one runner posts batches sequentially
372:     const { m: maxSeq } = await env.DB.prepare('SELECT COALESCE(MAX(seq), -1) AS m FROM run_logs WHERE run_id = ?').bind(runId).first();
373:     let seq = maxSeq;
374:     const stmt = env.DB.prepare('INSERT INTO run_logs (run_id, seq, line) VALUES (?, ?, ?)');
375:     await env.DB.batch(lines.map((l) => stmt.bind(runId, ++seq, String(l))));
376:   }
377:   if (exitCode !== undefined && exitCode !== null) {
378:     await env.DB.prepare("UPDATE runs SET status = ?, exit_code = ?, finished_at = datetime('now') WHERE run_id = ?")
379:       .bind(exitCode === 0 ? 'finished' : 'failed', exitCode, runId)
380:       .run();
381:   }
382:   return json({ ok: true });
383: }
