427: async function proxyApp(req, env, org, name, rest, baseUrl) {
428:   const sess = await sessionOf(req, env);
429:   const prefix = `/a/${org}/${name}`;
430:   if (!sess) {
431:     if (req.method !== 'GET') return json({ error: 'login required' }, 401);
432:     return new Response(null, { status: 302, headers: { Location: `${baseUrl}/login?next=${encodeURIComponent(prefix + '/')}` } });
433:   }
434:   const app = await appRow(env, org, name);
435:   if (!app) return html(`<p>No app <b>${name}</b> here.</p>`, 404);
436:   if (!(await canView(env, app, sess.email))) return html(`<p><b>${sess.email}</b> does not have access to <b>${name}</b>. Ask the owner to run <code>small share ${sess.email}</code>.</p>`, 403);
437:   if (rest === '') return new Response(null, { status: 301, headers: { Location: `${prefix}/` } }); // relative URLs need the trailing slash
438: 
439:   const origin = `https://${app.fly_app}.fly.dev`;
440:   const target = new URL(req.url);
441:   const headers = new Headers(req.headers);
442:   headers.delete('Cookie'); // the app never sees the session
443:   headers.delete('X-Small-Session');
444:   headers.set('X-Small-User', sess.email);
445:   headers.set('X-Small-Org', org);
446:   headers.set('X-Small-Proxy', app.proxy_secret);
447:   let resp;
448:   for (let attempt = 0; ; attempt++) {
449:     resp = await fetch(`${origin}${rest}${target.search}`, {
450:       method: req.method,
451:       headers,
452:       body: ['GET', 'HEAD'].includes(req.method) ? undefined : req.body,
453:       redirect: 'manual',
454:     });
455:     // Fly answers 502/503 while a scaled-to-zero machine wakes (~30s for torch-heavy apps);
456:     // hold safe-to-repeat requests instead of showing the browser a Bad Gateway.
457:     if (![502, 503].includes(resp.status) || !['GET', 'HEAD'].includes(req.method) || attempt >= 9) break;
458:     await new Promise((r) => setTimeout(r, 5000));
459:   }
460:   const out = new Headers(resp.headers);
461:   const loc = out.get('Location');
462:   if (loc && loc.startsWith('/') && !loc.startsWith('/a/')) out.set('Location', prefix + loc); // path-based hosting: re-prefix app redirects
463:   return new Response(resp.body, { status: resp.status, headers: out });
464: }
