466: export default {
467:   async fetch(req, env, ctx) {
468:     const url = new URL(req.url);
469:     const baseUrl = `${url.protocol}//${url.host}`;
470:     const path = url.pathname;
471:     try {
472:       if (path === '/api/cli/login' && req.method === 'POST') return await apiLogin(req, env);
473:       if (path === '/api/cli/verify' && req.method === 'POST') return await apiVerify(req, env);
474:       if (path === '/api/runtime/aws-creds' && req.method === 'POST') return await apiAwsCreds(req, env);
475:       if (path.startsWith('/api/')) {
476:         const runLog = path.match(/^\/api\/runs\/([\w-]+)\/log$/);
477:         if (runLog && req.method === 'POST') return await apiRunLog(req, env, runLog[1]); // runner auth, not CLI auth
478:         const reqLog = path.match(/^\/api\/apps\/([a-z0-9-]+)\/request-log$/);
479:         if (reqLog && req.method === 'POST') return await apiRequestLogIngest(req, env, reqLog[1]); // guard auth, not CLI auth
480:         const user = await cliAuth(req, env);
481:         if (!user) return json({ error: 'run small login first' }, 401);
482:         if (path === '/api/deploy' && req.method === 'POST') return await apiDeploy(req, env, ctx, user, baseUrl);
483:         if (path === '/api/image' && req.method === 'POST') return await apiImage(req, env, user);
484:         if (path === '/api/runs' && req.method === 'POST') return await apiRunStart(req, env, user, baseUrl);
485:         if (path === '/api/runs' && req.method === 'GET') return await apiRunsList(req, env, user);
486:         const runGet = path.match(/^\/api\/runs\/([\w-]+)$/);
487:         if (runGet && req.method === 'GET') return await apiRunGet(req, env, user, runGet[1]);
488:         if (path === '/api/schedule' && req.method === 'POST') return await apiSchedulePause(req, env, user);
489:         if (path === '/api/share' && req.method === 'POST') return await apiShare(req, env, user);
490:         if (path === '/api/apps' && req.method === 'GET') return await apiApps(env, user);
491:         if (path === '/api/logs' && req.method === 'GET') return await apiLogs(req, env, user);
492:         if (path === '/api/request-logs' && req.method === 'GET') return await apiRequestLogs(req, env, user);
493:         if (path === '/api/review' && req.method === 'GET') return await apiReview(req, env, user);
494:         if (path === '/api/runbook' && req.method === 'POST') return await apiRunbook(req, env);
495:         if (path === '/api/review/run' && req.method === 'POST') return await apiReviewRun(req, env, user);
496:         return json({ error: 'no such endpoint' }, 404);
497:       }
498:       if (path === '/login') return await loginPage(req, env, baseUrl);
499:       if (path === '/auth') return await authRedirect(req, env);
500:       if (path === '/test/session' && req.method === 'POST') return await testSession(req, env);
501:       const m = path.match(/^\/a\/([a-z0-9-]+)\/([a-z0-9-]+)(\/.*)?$/);
502:       if (m) return await proxyApp(req, env, m[1], m[2], m[3] || '', baseUrl);
503:       if (path === '/') return html('<h2>small</h2><p>Deploy a Python app behind a login in one command: <code>npm i -g small-deploy</code></p>');
504:       return html('<p>Not found.</p>', 404);
505:     } catch (err) {
506:       return json({ error: `internal: ${err.message}` }, 500);
507:     }
508:   },
509: 
510:   // Two crons (wrangler.jsonc): "0 3 * * *" purges request_logs, "* * * * *" runs due jobs.
511:   async scheduled(event, env, ctx) {
512:     if (event.cron === '0 3 * * *') {
513:       // 7-day request-log retention. Cutoff formatted with 'T' to match the guard's ISO timestamps.
514:       // ponytail: retention fixed at 7 days — make it a per-app column when someone needs more
515:       await env.DB.prepare("DELETE FROM request_logs WHERE ts < strftime('%Y-%m-%dT%H:%M:%S', 'now', '-7 days')").run();
516:       return;
517:     }
518:     // Every-minute tick. scheduledTime is the tick's nominal minute even when
519:     // delivery is late; last_scheduled_at pins each fired minute so a duplicate
520:     // or late tick never double-fires.
521:     // ponytail: no catch-up after downtime — a missed minute is just missed.
522:     const tick = Math.floor(event.scheduledTime / 60000) * 60; // unix seconds, floored to the minute
523:     const { results } = await env.DB.prepare(
524:       "SELECT * FROM apps WHERE kind = 'job' AND schedule IS NOT NULL AND schedule_paused = 0 AND image IS NOT NULL"
525:     ).all();
526:     for (const app of results) {
527:       let parsed;
528:       try {
529:         parsed = parseCron(app.schedule);
530:       } catch {
531:         continue; // validated at deploy; a bad legacy row must not kill the whole tick
532:       }
533:       if (!matches(parsed, new Date(tick * 1000)) || (app.last_scheduled_at || 0) >= tick) continue;
534:       await env.DB.prepare('UPDATE apps SET last_scheduled_at = ? WHERE id = ?').bind(tick, app.id).run();
535:       // ponytail: a run whose machine died before posting an exit code stays 'running'
536:       // and blocks cron forever; add a max-age cutoff when it bites.
537:       const running = await env.DB.prepare("SELECT 1 AS x FROM runs WHERE app_id = ? AND status = 'running' LIMIT 1").bind(app.id).first();
538:       if (running) {
539:         await env.DB.prepare(
540:           "INSERT INTO runs (run_id, app_id, started_by, status, reason, finished_at) VALUES (?, ?, 'cron', 'skipped', 'previous run still active', datetime('now'))"
541:         ).bind('r-' + randomHex(6), app.id).run();
542:         continue;
543:       }
544:       try {
545:         await startRun(env, app, 'cron', env.BASE_URL);
546:       } catch (e) {
547:         console.error(`cron: ${app.org}/${app.name}: ${e.message}`); // run row already marked failed
548:       }
549:     }
550:   },
551: };

