60: function printReport(res) {
61:   const r = res.review;
62:   const section = (title, key) => {
63:     if (!(r[key] || []).length) return;
64:     console.log(`${title}:`);
65:     for (const x of r[key]) console.log(`  ${reviewFmt[key](x)}`);
66:   };
67:   section('findings', 'findings');
68:   section('secrets', 'secrets');
69:   section('undeclared secrets', 'undeclared_secrets');
70:   section('outbound', 'outbound');
71:   section('aws', 'aws');
72:   section('shell exec', 'shell_exec');
73:   const fsys = r.filesystem || { reads: [], writes: [] };
74:   console.log('filesystem:');
75:   console.log(`  reads: ${fsys.reads.join(', ') || '—'}`);
76:   console.log(`  writes: ${fsys.writes.join(', ') || '—'}`);
77:   if ((r.skipped || []).length) console.log(`skipped: ${r.skipped.join(', ')}`);
78:   console.log(`summary: ${r.summary}`);
79:   console.log(`risk: ${r.risk} (${res.model || 'unknown model'}, ${res.reviewedAt})`);
80: }
