82: function printDiff(res) {
83:   if (!res.prev) return console.log('no previous review to diff against');
84:   const { prev, review: cur } = res;
85:   let changed = false;
86:   if (prev.risk !== cur.risk) {
87:     console.log(`risk: ${prev.risk} → ${cur.risk}`);
88:     changed = true;
89:   }
90:   for (const key of Object.keys(reviewFmt)) {
91:     const before = new Set((prev[key] || []).map(reviewFmt[key]));
92:     const after = new Set((cur[key] || []).map(reviewFmt[key]));
93:     for (const s of after) if (!before.has(s)) (changed = true), console.log(`+ ${key.replace('_', ' ')}: ${s}`);
94:     for (const s of before) if (!after.has(s)) (changed = true), console.log(`- ${key.replace('_', ' ')}: ${s}`);
95:   }
96:   for (const dir of ['reads', 'writes']) {
97:     const before = new Set((prev.filesystem || {})[dir] || []);
98:     const after = new Set((cur.filesystem || {})[dir] || []);
99:     for (const s of after) if (!before.has(s)) (changed = true), console.log(`+ filesystem ${dir}: ${s}`);
100:     for (const s of before) if (!after.has(s)) (changed = true), console.log(`- filesystem ${dir}: ${s}`);
101:   }
102:   if (!changed) console.log('no changes since previous deploy');
