146: 
147:     const envPath = path.resolve(dir, typeof flags.env === 'string' ? flags.env : '.env');
148:     const secrets = envfile.parse(envPath);
149:     const required = (app.config.secrets && app.config.secrets.required) || [];
150:     const missing = required.filter((k) => !(k in secrets));
151:     if (missing.length) throw new Error(`missing secrets: ${missing.join(', ')} — add them to ${envPath}`);
152: 
153:     write(dir, app);
154:     const review = buildBundle(dir, app.entry, secrets);
155:     const visibility = (app.config.access && app.config.access.visibility) || undefined;
156:     const storage = app.config.storage;
157:     let sizeGb;
158:     if (storage) {
159:       const m = /^(\d+)\s*gb$/i.exec(String(storage.size || '1GB'));
160:       if (!m) throw new Error('storage.size must be whole gigabytes, like "1GB"');
161:       sizeGb = Number(m[1]);
162:     }
163:     const awsRoleArn = (app.config.aws && app.config.aws.role_arn) || undefined;
164:     const kind = app.config.kind === 'job' ? 'job' : 'server';
165:     const schedule = app.config.schedule;
166:     const d = await call('POST', '/api/deploy', {
167:       name: app.name,
168:       framework: app.framework,
169:       visibility,
170:       awsRoleArn,
171:       kind,
172:       storage: storage ? { sizeGb } : undefined,
173:       schedule: kind === 'job' ? schedule || null : undefined, // null clears a removed schedule
174:     });
175:     if (!d.flyToken) throw new Error('control plane has no FLY_API_TOKEN configured');
176:     if (storage && !d.volumeRegion) throw new Error('control plane does not support [storage] yet — redeploy the worker');
177:     writeFlyToml(dir, d.flyApp, app.config.memory, storage ? { path: storage.path || '/data', region: d.volumeRegion } : undefined);
178:     if (storage) console.log(`✓ storage: ${storage.path || '/data'} (${sizeGb}GB volume in ${d.volumeRegion}, survives redeploys)`);
179: 
180:     // The worker's waitUntil window (~30s) is too short for the model to write review +
181:     // runbook, so the CLI holds this request open in parallel with the Fly build instead;
182:     // the worker awaits the model and stores the result before responding.
183:     const reviewPromise = call('POST', '/api/review/run', {
184:       app: app.name,
185:       bundle: review.bundle,
186:       skipped: review.skipped,
187:     }).catch(() => null);
188:     const printReview = async () => {
189:       const res = await reviewPromise;
190:       if (res && res.review) console.log(reviewLine(res.review));
191:       else console.log('review: unavailable');
192:     };
193: 
194:     if (kind === 'job') {
195:       if (schedule) {
196:         if (!d.nextRun && !d.schedulePaused) throw new Error('control plane does not support schedule yet — redeploy the worker');
197:         const next = d.schedulePaused
198:           ? `paused — small schedule resume ${app.name}`
199:           : `next run ${new Date(d.nextRun).toISOString().slice(0, 16).replace('T', ' ')}`;
200:         console.log(`✓ schedule: ${schedule} (UTC) · ${next}`);
201:       }
202:       // jobs: build + register the image, start nothing — the control plane starts machines per run
203:       fly.setSecrets(d.flyApp, d.flyToken, secrets);
204:       const image = fly.buildImage(d.flyApp, d.flyToken, dir, `v${Date.now()}`);
205:       await call('POST', '/api/image', { app: app.name, image });
206:       console.log(`✓ built ${app.name} — start it with: small run ${app.name}`);
207:       await printReview();
208:       return;
209:     }
210: 
211:     // gradio builds asset/API URLs from its root; behind the path proxy that must be the public URL
212:     const rootPath = app.framework === 'gradio' ? { GRADIO_ROOT_PATH: d.url.replace(/\/$/, '') } : {};
213:     // [aws] role: guard fetches STS session creds from the control plane at boot
214:     const cpUrl = awsRoleArn ? { SMALL_CP_URL: apiBase() } : {};
215:     // guard batches request-log lines here, authed by the proxy secret it already holds
216:     const logUrl = { SMALL_LOG_URL: `${apiBase()}/api/apps/${app.name}/request-log` };
217:     fly.setSecrets(d.flyApp, d.flyToken, { SMALL_PROXY_SECRET: d.proxySecret, ...rootPath, ...cpUrl, ...logUrl, ...secrets });
218:     if (awsRoleArn) console.log(`✓ aws role: ${awsRoleArn} (STS via control plane)`);
219:     fly.deploy(d.flyApp, d.flyToken, dir);
220: 
221:     console.log(`✓ deployed → ${d.url}`);
222:     const { org } = config.load();
223:     console.log(visibility === 'private' ? '✓ login required · explicit members only' : `✓ login required · anyone @${org}`);
224:     await printReview();
225:   },
