238:     const cur = res.review && res.review.runbook;
239:     if (!cur) return console.log('runbook: unavailable — no reviewed deploy yet');
240:     if (flags.diff) {
241:       const prev = res.prev && res.prev.runbook;
242:       if (!prev) return console.log('no previous runbook to diff against');
243:       // ponytail: line-set diff, no ordering — mirror of review --diff; real diff when it matters
244:       const before = new Set(prev.split('\n'));
245:       const after = new Set(cur.split('\n'));
246:       let changed = false;
247:       for (const l of cur.split('\n')) if (!before.has(l)) (changed = true), console.log(`+ ${l}`);
248:       for (const l of prev.split('\n')) if (!after.has(l)) (changed = true), console.log(`- ${l}`);
249:       if (!changed) console.log('no changes since previous deploy');
